// Generated by Suite Builder from a crawl of the site. The link report: every address the crawl requested, asked again (LinkReportTest).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The addresses are the crawl's: suite build writes them, in src/test/resources/link-report/.
package com.playwrightplayground.tests.core;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.function.ToIntFunction;

/**
 * The link report (G-118): every address the crawl requested, asked once more by HTTP, what it
 * answers now beside what it answered then, in target/link-report.md. One that answered 2xx in the
 * crawl and does not now is broken since: LinkReportTest fails on it. One already broken in the
 * crawl is listed as known, never failed again; the rest are listed as fine.
 */
public final class LinkReport {
    public static final Path REPORT = Path.of("target", "link-report.md");
    /** The addresses, written by Suite Builder from the crawl: path, status then ("-": no answer), pages linking to it. */
    private static final String LINKS = "/link-report/links.tsv";

    private LinkReport() {}

    /**
     * Asks every address ({@code statusOf}: its status now; an exception counts as no answer), one
     * after another and with the suite's pause between them (-DtestDelay), writes the report and
     * returns what is broken since the crawl, one sentence each. When the first address asked gets no
     * answer at all, the rest are not asked, each waiting out its timeout: the site cannot be reached,
     * and the failure says so (StopEarly then stops the run).
     */
    public static List<String> check(ToIntFunction<String> statusOf) {
        List<String[]> links = read();
        StepLog.step("Ask the " + links.size() + " addresses the crawl requested, once each (" + REPORT + ")");
        List<String> since = new ArrayList<>();
        List<String> brokenRows = new ArrayList<>();
        List<String> knownRows = new ArrayList<>();
        List<String> fineRows = new ArrayList<>();
        for (String[] link : links) {
            Pace.betweenRequests();
            int now;
            try {
                now = statusOf.applyAsInt(link[0]);
            } catch (RuntimeException e) {
                if (fineRows.isEmpty() && brokenRows.isEmpty() && knownRows.isEmpty()) {
                    write(List.of("| " + link[0] + " | " + said(link[1].equals("-") ? 0 : Integer.parseInt(link[1])) + " | no answer | " + link[2] + " |"), knownRows, fineRows);
                    throw new AssertionError("The site cannot be reached: " + link[0] + " gave no answer (" + e.getMessage()
                            + "); the other " + (links.size() - 1) + " addresses were not asked");
                }
                now = 0;
            }
            int then = link[1].equals("-") ? 0 : Integer.parseInt(link[1]);
            String row = "| " + link[0] + " | " + said(then) + " | " + said(now) + " | " + link[2] + " |";
            if (ok(then) && !ok(now)) {
                brokenRows.add(row);
                since.add(link[0] + " answered " + said(now) + " (" + then + " in the crawl)");
            } else if (!ok(then)) {
                knownRows.add(row);
            } else {
                fineRows.add(row);
            }
        }
        write(brokenRows, knownRows, fineRows);
        return since;
    }

    private static boolean ok(int status) {
        return status >= 200 && status < 300;
    }

    private static String said(int status) {
        return status == 0 ? "no answer" : String.valueOf(status);
    }

    private static List<String[]> read() {
        List<String[]> out = new ArrayList<>();
        InputStream in = LinkReport.class.getResourceAsStream(LINKS);
        if (in == null) throw new IllegalStateException(LINKS + " is missing: rebuild the suite (suite build <project>) to put it back.");
        try (BufferedReader lines = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            for (String line = lines.readLine(); line != null; line = lines.readLine()) {
                if (line.isBlank() || line.startsWith("#")) continue;
                String[] cells = (line + "\t\t").split("\t", -1);
                out.add(new String[] {cells[0], cells[1], cells[2].replace(" ", ", ")});
            }
        } catch (IOException e) {
            throw new IllegalStateException("could not read " + LINKS + ": " + e.getMessage(), e);
        }
        return out;
    }

    private static void write(List<String> broken, List<String> known, List<String> fine) {
        StringBuilder md = new StringBuilder("# Link report\n\nEvery address the crawl requested, asked again by this run. One that answered in the crawl\n"
                + "and does not now fails LinkReportTest; one already broken in the crawl is listed as known.\n");
        section(md, "Broken since the crawl", broken);
        section(md, "Broken in the crawl, still listed", known);
        section(md, "Answering as in the crawl", fine);
        try {
            Files.createDirectories(REPORT.getParent());
            Files.writeString(REPORT, md.toString(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            System.out.println("   note: could not write " + REPORT + ": " + e.getMessage());
        }
    }

    private static void section(StringBuilder md, String title, List<String> rows) {
        md.append("\n## ").append(title).append(" (").append(rows.size()).append(")\n\n");
        if (rows.isEmpty()) {
            md.append("None.\n");
            return;
        }
        md.append("| Address | In the crawl | Now | Linked from |\n| --- | --- | --- | --- |\n");
        for (String row : rows) md.append(row).append('\n');
    }
}
